{/* Task List - TasksPage.tsx içindeki ilgili kısım */}
<div className="grid gap-3">
  {tasks.length === 0 ? (
    <div className="text-center py-10 opacity-40 italic">Geen taken gevonden...</div>
  ) : (
    tasks.map((t, i) => (
      <div
        key={i}
        className="p-4 rounded-lg bg-[#16255a]/60 border border-teal-300/20 hover:border-teal-300/50 transition-all group"
      >
        <div className="flex justify-between items-start">
          <div>
            <h3 className="font-bold text-teal-100 group-hover:text-fuchsia-300 transition-colors">
              {t.title} {/* t.task değil, t.title */}
            </h3>
            <p className="text-xs text-teal-400/70 mt-1">
              📄 {t.document}
            </p>
          </div>
          <span className="text-[10px] bg-fuchsia-500/20 text-fuchsia-300 px-2 py-1 rounded border border-fuchsia-500/30">
            Sprint {t.sprint}
          </span>
        </div>
        <div className="flex justify-between items-center mt-3 pt-2 border-t border-teal-300/10">
           <span className="text-[10px] opacity-60 italic">{t.createdAt}</span>
           <span className="text-xs font-bold text-teal-300">{t.hours} uur</span>
        </div>
      </div>
    ))
  )}
</div>